app_css:
.tool-app-renewguard { color: #2e1065; max-width: 920px; margin-inline: auto; }
.tool-app-renewguard .rg-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 10px; margin: 12px 0; }
.tool-app-renewguard .rg-stat { background: #f5f3ff; border: 1px solid #ddd6fe; border-radius: 12px; padding: 12px 14px; display: flex; flex-direction: column; gap: 4px; }
.tool-app-renewguard .rg-stat span { font-size: 12px; font-weight: 600; color: #5b21b6; }
.tool-app-renewguard .rg-stat strong { font-size: 22px; }
.tool-app-renewguard .rg-stat-warn { background: #fffbeb; border-color: #fde68a; }
.tool-app-renewguard .rg-stat-warn span { color: #92400e; }
.tool-app-renewguard .rg-stat-risk { background: #fef2f2; border-color: #fecaca; }
.tool-app-renewguard .rg-stat-risk span { color: #991b1b; }
.tool-app-renewguard .rg-intro { font-size: 14px; line-height: 1.55; color: #4c1d95; margin: 10px 0 14px; }
.tool-app-renewguard .rg-form { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 10px; background: #fafaff; border: 1px solid #e9d5ff; border-radius: 14px; padding: 14px; margin: 12px 0; align-items: end; }
.tool-app-renewguard label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; }
.tool-app-renewguard input[type="text"], .tool-app-renewguard input[type="number"], .tool-app-renewguard input[type="date"], .tool-app-renewguard select { border: 1px solid #c4b5fd; border-radius: 8px; padding: 8px 10px; font-size: 14px; width: 100%; box-sizing: border-box; background: #fff; }
.tool-app-renewguard .rg-check { flex-direction: row; align-items: center; gap: 8px; font-size: 13px; padding-bottom: 9px; }
.tool-app-renewguard .rg-check input { width: 18px; height: 18px; accent-color: #6D28D9; }
.tool-app-renewguard .rg-btn { background: #6D28D9; color: #fff; border: none; border-radius: 10px; padding: 10px 18px; font-size: 14px; font-weight: 700; cursor: pointer; }
.tool-app-renewguard .rg-btn:hover { background: #5b21b6; }
.tool-app-renewguard .rg-btn-ghost { background: #ede9fe; color: #5b21b6; }
.tool-app-renewguard .rg-btn-ghost:hover { background: #ddd6fe; }
.tool-app-renewguard .rg-btn-small { padding: 7px 12px; font-size: 13px; border-radius: 8px; }
.tool-app-renewguard .rg-toolbar { display: flex; gap: 12px; flex-wrap: wrap; align-items: end; margin: 16px 0 10px; }
.tool-app-renewguard .rg-search { flex: 1 1 200px; }
.tool-app-renewguard .rg-toolbar-btns { display: flex; gap: 8px; margin-left: auto; }
.tool-app-renewguard .rg-list { display: flex; flex-direction: column; gap: 10px; }
.tool-app-renewguard .rg-card { border: 1px solid #e9d5ff; border-left: 6px solid #a78bfa; border-radius: 12px; padding: 12px 14px; background: #fff; }
.tool-app-renewguard .rg-card-act { border-left-color: #d97706; background: #fffbeb; }
.tool-app-renewguard .rg-card-missed { border-left-color: #dc2626; background: #fef2f2; }
.tool-app-renewguard .rg-card-closed { opacity: 0.62; border-left-color: #9ca3af; background: #f9fafb; }
.tool-app-renewguard .rg-card-head { display: flex; justify-content: space-between; gap: 10px; flex-wrap: wrap; align-items: baseline; }
.tool-app-renewguard .rg-card-head h4 { margin: 0; font-size: 16px; }
.tool-app-renewguard .rg-badge { font-size: 12px; font-weight: 800; border-radius: 999px; padding: 4px 10px; background: #ede9fe; color: #5b21b6; white-space: nowrap; }
.tool-app-renewguard .rg-badge-act { background: #fef3c7; color: #92400e; }
.tool-app-renewguard .rg-badge-missed { background: #fee2e2; color: #991b1b; }
.tool-app-renewguard .rg-badge-safe { background: #dcfce7; color: #166534; }
.tool-app-renewguard .rg-meta { display: flex; gap: 16px; flex-wrap: wrap; font-size: 13px; color: #4c1d95; margin: 8px 0; }
.tool-app-renewguard .rg-meta b { color: #2e1065; }
.tool-app-renewguard .rg-notes-line { font-size: 13px; color: #6b7280; margin: 4px 0 8px; }
.tool-app-renewguard .rg-actions { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 8px; }
.tool-app-renewguard .rg-del { background: none; border: none; color: #b91c1c; font-weight: 700; cursor: pointer; font-size: 13px; padding: 7px 6px; }
.tool-app-renewguard .rg-empty { color: #6b7280; font-size: 14px; padding: 14px; border: 1px dashed #c4b5fd; border-radius: 12px; text-align: center; }
.tool-app-renewguard .tool-print-doc { display: none; }
@media print {
  .tool-app-renewguard .rg-screen { display: none !important; }
  .tool-app-renewguard .tool-print-doc { display: block !important; color: #000; }
  .tool-app-renewguard .tool-print-doc table { width: 100%; border-collapse: collapse; margin: 12px 0; }
  .tool-app-renewguard .tool-print-doc th, .tool-app-renewguard .tool-print-doc td { border: 1px solid #999; padding: 6px; text-align: left; font-size: 13px; }
}

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(n) { n = parseFloat(n); return '$' + (isFinite(n) ? n : 0).toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 2 }); }
  var root = $('toolAppRoot');
  var LS_KEY = 'toolapp-renewguard-contracts';
  var DAY = 86400000;
  function parseDate(v) {
    if (!v) return null;
    var p = String(v).split('-');
    if (p.length !== 3) return null;
    return new Date(parseInt(p[0], 10), parseInt(p[1], 10) - 1, parseInt(p[2], 10));
  }
  function fmtDate(d) {
    if (!d) return '';
    return d.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
  }
  function toISO(d) {
    var m = String(d.getMonth() + 1); if (m.length < 2) m = '0' + m;
    var day = String(d.getDate()); if (day.length < 2) day = '0' + day;
    return d.getFullYear() + '-' + m + '-' + day;
  }
  function todayStart() { var t = new Date(); return new Date(t.getFullYear(), t.getMonth(), t.getDate()); }
  function noticeDate(item) {
    var r = parseDate(item.renewal);
    if (!r) return null;
    return new Date(r.getTime() - (parseInt(item.notice, 10) || 0) * DAY);
  }
  function daysBetween(a, b) { return Math.round((b.getTime() - a.getTime()) / DAY); }
  function annualCost(item) {
    var c = parseFloat(item.cost) || 0;
    if (item.cycle === 'weekly') return c * 52;
    if (item.cycle === 'monthly') return c * 12;
    if (item.cycle === 'quarterly') return c * 4;
    return c;
  }
  function statusOf(item) {
    if (item.status && item.status !== 'active') return { key: 'closed', label: item.status === 'cancelled' ? 'Cancelled' : 'Renewed / closed' };
    var t = todayStart();
    var nd = noticeDate(item);
    var rd = parseDate(item.renewal);
    if (!nd || !rd) return { key: 'safe', label: 'No date' };
    var dNotice = daysBetween(t, nd);
    var dRenew = daysBetween(t, rd);
    if (dRenew < 0) return { key: 'missed', label: 'Renewal date passed' };
    if (dNotice < 0) return { key: 'missed', label: 'Notice window missed' };
    if (dNotice <= 7) return { key: 'act', label: 'Act now - ' + dNotice + (dNotice === 1 ? ' day' : ' days') + ' to notice deadline' };
    if (dNotice <= 30) return { key: 'soon', label: 'Decide soon - ' + dNotice + ' days to notice deadline' };
    return { key: 'safe', label: 'Safe - ' + dNotice + ' days to notice deadline' };
  }
  function getItems() {
    try { return JSON.parse(localStorage.getItem(LS_KEY)) || []; } catch (e) { return []; }
  }
  function setItems(items) {
    try { localStorage.setItem(LS_KEY, JSON.stringify(items)); } catch (e) {}
  }
  function advanceDate(item) {
    var r = parseDate(item.renewal);
    if (!r) return item.renewal;
    if (item.cycle === 'weekly') r = new Date(r.getTime() + 7 * DAY);
    else if (item.cycle === 'monthly') r = new Date(r.getFullYear(), r.getMonth() + 1, r.getDate());
    else if (item.cycle === 'quarterly') r = new Date(r.getFullYear(), r.getMonth() + 3, r.getDate());
    else r = new Date(r.getFullYear() + 1, r.getMonth(), r.getDate());
    return toISO(r);
  }
  function render() {
    var items = getItems();
    var t = todayStart();
    var active = items.filter(function (i) { return !i.status || i.status === 'active'; });
    var yearTotal = 0, urgent = 0, risk = 0;
    active.forEach(function (i) {
      yearTotal += annualCost(i);
      var nd = noticeDate(i);
      if (nd) {
        var d = daysBetween(t, nd);
        if (d <= 30) { urgent++; risk += annualCost(i); }
      }
    });
    $('rg-stat-count').textContent = String(active.length);
    $('rg-stat-year').textContent = money(yearTotal);
    $('rg-stat-urgent').textContent = String(urgent);
    $('rg-stat-risk').textContent = money(risk);
    var filter = $('rg-filter').value;
    var q = $('rg-search').value.trim().toLowerCase();
    var shown = items.slice();
    shown.sort(function (a, b) {
      var ac = (!a.status || a.status === 'active') ? 0 : 1;
      var bc = (!b.status || b.status === 'active') ? 0 : 1;
      if (ac !== bc) return ac - bc;
      var an = noticeDate(a), bn = noticeDate(b);
      return (an ? an.getTime() : 0) - (bn ? bn.getTime() : 0);
    });
    shown = shown.filter(function (i) {
      var st = statusOf(i);
      if (filter === 'all' && st.key === 'closed') return false;
      if (filter === 'closed' && st.key !== 'closed') return false;
      if (filter === 'act' && st.key !== 'act') return false;
      if (filter === 'soon' && st.key !== 'soon' && st.key !== 'act') return false;
      if (filter === 'missed' && st.key !== 'missed') return false;
      if (filter === 'safe' && st.key !== 'safe') return false;
      if (q && (String(i.name) + ' ' + String(i.vendor || '')).toLowerCase().indexOf(q) === -1) return false;
      return true;
    });
    var list = $('rg-list');
    list.innerHTML = '';
    $('rg-empty').style.display = shown.length ? 'none' : 'block';
    if (!items.length) $('rg-empty').textContent = 'No contracts yet. Add the first one above - start with the subscription you most regret auto-renewing.';
    else if (!shown.length) $('rg-empty').textContent = 'Nothing matches this filter.';
    shown.forEach(function (item) {
      var st = statusOf(item);
      var card = document.createElement('div');
      card.className = 'rg-card' + (st.key === 'act' || st.key === 'soon' ? ' rg-card-act' : '') + (st.key === 'missed' ? ' rg-card-missed' : '') + (st.key === 'closed' ? ' rg-card-closed' : '');
      var badgeCls = st.key === 'missed' ? 'rg-badge rg-badge-missed' : (st.key === 'act' || st.key === 'soon' ? 'rg-badge rg-badge-act' : (st.key === 'safe' ? 'rg-badge rg-badge-safe' : 'rg-badge'));
      var nd = noticeDate(item);
      var html = '<div class="rg-card-head"><h4>' + esc(item.name) + '</h4><span class="' + badgeCls + '">' + esc(st.label) + '</span></div>';
      html += '<div class="rg-meta">';
      if (item.vendor) html += '<span>Vendor: <b>' + esc(item.vendor) + '</b></span>';
      html += '<span>Category: <b>' + esc(item.category || 'Other') + '</b></span>';
      html += '<span>Notice deadline: <b>' + esc(fmtDate(nd)) + '</b></span>';
      html += '<span>Renews: <b>' + esc(fmtDate(parseDate(item.renewal))) + '</b></span>';
      html += '<span>Cost: <b>' + money(item.cost) + ' / ' + esc(item.cycle || 'yearly') + '</b> (' + money(annualCost(item)) + '/yr)</span>';
      html += '<span>' + (item.auto ? 'Auto-renews' : 'Manual renewal') + ' - ' + (parseInt(item.notice, 10) || 0) + ' days notice</span>';
      html += '</div>';
      if (item.notes) html += '<p class="rg-notes-line">' + esc(item.notes) + '</p>';
      html += '<div class="rg-actions">';
      if (st.key !== 'closed') {
        html += '<button type="button" class="rg-btn rg-btn-small" data-act="renewed" data-id="' + esc(item.id) + '">Mark renewed</button>';
        html += '<button type="button" class="rg-btn rg-btn-ghost rg-btn-small" data-act="cancelled" data-id="' + esc(item.id) + '">Mark cancelled</button>';
      } else {
        html += '<button type="button" class="rg-btn rg-btn-ghost rg-btn-small" data-act="reactivate" data-id="' + esc(item.id) + '">Reactivate</button>';
      }
      html += '<button type="button" class="rg-del" data-act="delete" data-id="' + esc(item.id) + '">Delete</button>';
      html += '</div>';
      card.innerHTML = html;
      list.appendChild(card);
    });
    renderPrint(items);
  }
  function renderPrint(items) {
    var active = items.filter(function (i) { return !i.status || i.status === 'active'; });
    active.sort(function (a, b) { var an = noticeDate(a), bn = noticeDate(b); return (an ? an.getTime() : 0) - (bn ? bn.getTime() : 0); });
    var rows = '';
    var total = 0;
    active.forEach(function (i) {
      total += annualCost(i);
      rows += '<tr><td>' + esc(i.name) + '</td><td>' + esc(i.vendor || '') + '</td><td>' + esc(fmtDate(noticeDate(i))) + '</td><td>' + esc(fmtDate(parseDate(i.renewal))) + '</td><td>' + esc(statusOf(i).label) + '</td><td>' + money(annualCost(i)) + '/yr</td></tr>';
    });
    $('rg-printdoc').innerHTML = '<h1>RenewGuard - renewal report</h1><p>Generated ' + esc(fmtDate(todayStart())) + '. Sorted by notice deadline - the last day to cancel or renegotiate before auto-renewal.</p><table><thead><tr><th>Contract</th><th>Vendor</th><th>Notice deadline</th><th>Renews</th><th>Status</th><th>Yearly cost</th></tr></thead><tbody>' + rows + '</tbody></table><h2>Total yearly spend tracked: ' + money(total) + '</h2>';
  }
  function exportCsv() {
    var items = getItems();
    var lines = ['Name,Vendor,Category,Notice deadline,Renewal date,Notice days,Cost,Cycle,Yearly cost,Auto-renews,Status,Notes'];
    function csv(v) { return '"' + String(v == null ? '' : v).replace(/"/g, '""') + '"'; }
    items.forEach(function (i) {
      lines.push([csv(i.name), csv(i.vendor || ''), csv(i.category || ''), csv(fmtDate(noticeDate(i))), csv(fmtDate(parseDate(i.renewal))), csv(i.notice), csv(i.cost), csv(i.cycle), csv(annualCost(i).toFixed(2)), csv(i.auto ? 'yes' : 'no'), csv(i.status || 'active'), csv(i.notes || '')].join(','));
    });
    var blob = new Blob([lines.join('\n')], { type: 'text/csv' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url; a.download = 'renewguard-contracts.csv';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(function () { URL.revokeObjectURL(url); }, 500);
  }
  $('rg-form').addEventListener('submit', function (e) {
    e.preventDefault();
    var name = $('rg-name').value.trim();
    var renewal = $('rg-renewal').value;
    if (!name || !renewal) return;
    var items = getItems();
    items.unshift({
      id: 'rg' + Date.now().toString(36) + Math.floor(Math.random() * 9999),
      name: name,
      vendor: $('rg-vendor').value.trim(),
      category: $('rg-category').value,
      renewal: renewal,
      notice: Math.max(0, Math.min(365, parseInt($('rg-notice').value, 10) || 0)),
      cost: Math.max(0, parseFloat($('rg-cost').value) || 0),
      cycle: $('rg-cycle').value,
      auto: $('rg-auto').checked,
      notes: $('rg-notes').value.trim(),
      status: 'active'
    });
    setItems(items);
    $('rg-name').value = ''; $('rg-vendor').value = ''; $('rg-notes').value = ''; $('rg-cost').value = '0';
    render();
  });
  root.addEventListener('input', function (e) {
    if (e.target.id === 'rg-search') render();
  });
  root.addEventListener('change', function (e) {
    if (e.target.id === 'rg-filter') render();
  });
  root.addEventListener('click', function (e) {
    var t = e.target;
    if (t.id === 'rg-print') { render(); window.print(); return; }
    if (t.id === 'rg-csv') { exportCsv(); return; }
    var act = t.getAttribute && t.getAttribute('data-act');
    if (!act) return;
    var id = t.getAttribute('data-id');
    var items = getItems();
    for (var i = 0; i < items.length; i++) {
      if (items[i].id !== id) continue;
      if (act === 'delete') items.splice(i, 1);
      else if (act === 'cancelled') items[i].status = 'cancelled';
      else if (act === 'reactivate') items[i].status = 'active';
      else if (act === 'renewed') { items[i].renewal = advanceDate(items[i]); items[i].status = 'active'; }
      break;
    }
    setItems(items);
    render();
  });
  (function init() {
    var d = new Date(); d.setDate(d.getDate() + 90);
    $('rg-renewal').value = toISO(d);
    render();
  })();
})();
